async function estimates(capability: string, input: unknown) {
  return Promise.all(bindingsFor(capability).filter(({ provider, binding }) => provider.commercialUseAllowed && binding.routable !== false).map(async ({ provider, binding }) => {
    try { return { providerId: provider.id, tier: binding.qualityTier, models: binding.models ?? [], costCents: (await binding.estimateCost(input)).cents, error: null as string | null } }
    catch (error) { return { providerId: provider.id, tier: binding.qualityTier, models: binding.models ?? [], costCents: null, error: (error as Error).message } }
  }))
}

function jsonOf(value: unknown): unknown {
  const text = value && typeof value === 'object' && typeof (value as { text?: unknown }).text === 'string' ? (value as { text: string }).text : ''
  for (const candidate of [text, text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, ''), text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)]) {
    try { if (candidate.trim()) return JSON.parse(candidate.trim()) } catch { /* siguiente */ }
  }
  return null
}

function enforceBudget(estimatedCents: number, maxCostCents: number, operation: string): void {
  if (!Number.isFinite(estimatedCents) || estimatedCents < 0) throw Object.assign(new Error(`Coste no estimable para ${operation}`), { code: 'MICROAPP_COST_UNAVAILABLE' })
  if (estimatedCents > maxCostCents) throw Object.assign(new Error(`${operation} supera el límite de gasto`), {
    code: 'MICROAPP_BUDGET_EXCEEDED', details: { operation, estimatedCents, maxCostCents },
  })
}

function uniqueStrings(values: string[]): boolean {
  return new Set(values.map(value => value.trim().toLowerCase())).size === values.length
}

function hasRecordedLicense(license: unknown): boolean {
  return Boolean(license && typeof license === 'object' && !Array.isArray(license) && Object.keys(license as Record<string, unknown>).length)
}

async function requireTenantReferenceAssets(ctx: { orgId: string }, assetIds: string[]): Promise<void> {
  if (!assetIds.length) return
  const now = new Date()
  const assets = await prisma.asset.findMany({
    where: { orgId: ctx.orgId, id: { in: assetIds } },
    select: { id: true, expiresAt: true, license: true },
  })
  const byId = new Map(assets.map(asset => [asset.id, asset]))
  const unauthorized = assetIds.filter(id => {
    const asset = byId.get(id)
    return !asset || !hasRecordedLicense(asset.license) || (asset.expiresAt != null && asset.expiresAt <= now)
  })
  if (unauthorized.length) {
    throw Object.assign(new Error('Hay referencias ausentes, vencidas o ajenas a la organización activa'), {
      code: 'REFERENCE_ASSET_NOT_AUTHORIZED',
      details: { assetIds: unauthorized },
    })
  }
}

async function requireTenantAssets(ctx: { orgId: string }, assetIds: string[]): Promise<void> {
  if (!assetIds.length) return
  const now = new Date()
  const assets = await prisma.asset.findMany({ where: { orgId: ctx.orgId, id: { in: assetIds } }, select: { id: true, expiresAt: true } })
  const available = new Set(assets.filter(asset => asset.expiresAt == null || asset.expiresAt > now).map(asset => asset.id))
  const unavailable = assetIds.filter(id => !available.has(id))
  if (unavailable.length) throw Object.assign(new Error('Hay assets ausentes, vencidos o ajenos a la organización activa'), { code: 'ASSET_NOT_AVAILABLE', details: { assetIds: unavailable } })
}

const evidenceClass = z.enum(['observado', 'aportado', 'inferido', 'sin_datos'])
const finding = z.object({ area: z.string(), finding: z.string(), severity: z.enum(['blocker', 'high', 'medium', 'low']), evidenceClass, evidenceRef: z.string(), action: z.string() })

