const castingInput = z.object({ roles: z.array(z.object({ id: z.string().trim().min(1), description: z.string().trim().min(5), actingRequirements: z.array(z.string().trim().min(2)).max(30) })).min(1).max(30), candidates: z.array(z.object({ id: z.string().trim().min(1), synthetic: z.boolean(), traits: z.array(z.string().trim().min(2)).min(1).max(40), voiceId: z.string().trim().min(1).optional(), faceAssetId: z.string().trim().min(1).optional(), consentGrantId: z.string().trim().min(1).optional(), allowedRegions: z.array(z.string().trim().min(2)).min(1), allowedChannels: z.array(z.string().trim().min(2)).min(1), exclusions: z.array(z.string().trim().min(2)).max(40) })).min(1).max(100), targetRegions: z.array(z.string().trim().min(2)).min(1).max(30).refine(uniqueStrings, 'Regiones duplicadas'), targetChannels: z.array(z.string().trim().min(2)).min(1).max(30).refine(uniqueStrings, 'Canales duplicados'), representationGoals: z.string().trim().max(3000).default('') }).superRefine((input, ctx) => {
  if (!uniqueStrings(input.roles.map(role => role.id))) ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['roles'], message: 'Los IDs de rol deben ser únicos' })
  if (!uniqueStrings(input.candidates.map(candidate => candidate.id))) ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['candidates'], message: 'Los IDs de candidato deben ser únicos' })
  input.candidates.forEach((candidate, index) => {
    if (!candidate.synthetic && !candidate.consentGrantId) ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['candidates', index, 'consentGrantId'], message: 'Una identidad real exige consentimiento' })
    if (!uniqueStrings(candidate.allowedRegions)) ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['candidates', index, 'allowedRegions'], message: 'Regiones duplicadas' })
    if (!uniqueStrings(candidate.allowedChannels)) ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['candidates', index, 'allowedChannels'], message: 'Canales duplicados' })
  })
})
const castingOutput = z.object({ casting: z.array(z.object({ roleId: z.string(), candidateId: z.string().nullable(), fitReasons: z.array(z.string()), rightsStatus: z.enum(['eligible', 'blocked', 'needs_review']), rightsReasons: z.array(z.string()), rehearsalPrompt: z.string() })), excludedCandidates: z.array(z.object({ candidateId: z.string(), reason: z.string() })), consentChecklist: z.array(z.object({ candidateId: z.string(), consentGrantId: z.string().nullable(), requiredScopes: z.array(z.string()), status: z.enum(['verified', 'synthetic', 'missing', 'blocked']) })), unresolvedRoles: z.array(z.string()) })

function scopeValues(scope: unknown, key: string): string[] {
  if (!scope || typeof scope !== 'object' || Array.isArray(scope)) return []
  const value = (scope as Record<string, unknown>)[key]
  return Array.isArray(value)
    ? value.filter((item): item is string => typeof item === 'string').map(item => item.trim().toLocaleLowerCase())
    : []
}

