registerMicroapp({
  id: 'product-video-generator', version: '1.0.0', name: 'Generador de vídeo de producto', category: 'studio',
  promise: 'Encola un vídeo de producto referenciado, con prompt de marca y revisión de claims', inputSchema: productVideoInput, outputSchema: productVideoOutput,
  uiSchema: [{ key: 'product', label: 'Producto y hechos verificables', widget: 'textarea' }, { key: 'objective', label: 'Objetivo', widget: 'text' }, { key: 'referenceAssetIds', label: 'Referencias', widget: 'textarea' }, { key: 'brandRules', label: 'Reglas de marca', widget: 'textarea' }, { key: 'durationS', label: 'Duración', widget: 'number' }, { key: 'aspectRatio', label: 'Formato', widget: 'select', options: ['9:16', '16:9', '1:1'].map(value => ({ value, label: value })) }, { key: 'quality', label: 'Calidad', widget: 'select', options: ['draft', 'final'].map(value => ({ value, label: value })) }, { key: 'providerId', label: 'Proveedor opcional', widget: 'text' }, { key: 'referenceRightsConfirmed', label: 'Derechos de referencias confirmados', widget: 'toggle' }, { key: 'maxGenerationCostCents', label: 'Presupuesto máximo (céntimos)', widget: 'number' }],
  capabilities: ['video.generate'], dataAccess: ['assets.read'], effects: 'local', freshnessDays: 90, followUps: [{ kind: 'open_job', label: 'Ver generación' }],
  async estimateCost(raw) { const input = productVideoInput.parse(raw); const cents = await getMicroappVideoEstimate(input); enforceBudget(cents, input.maxGenerationCostCents, 'Generación de vídeo de producto'); return { cents } },
  async run(ctx, raw): Promise<MicroappResult> {
    const input = productVideoInput.parse(raw); if (!ctx.enqueueCapability) throw new Error('Runtime sin jobs asíncronos')
    await requireTenantReferenceAssets(ctx, input.referenceAssetIds)
    const estimate = await getMicroappVideoEstimate(input)
    enforceBudget(estimate, input.maxGenerationCostCents, 'Generación de vídeo de producto')
    const prompt = `Vídeo de producto. Producto y hechos autorizados: ${input.product}. Objetivo: ${input.objective}. Reglas de marca: ${input.brandRules}. No añadir texto, logos, prestaciones ni resultados no descritos.`
    const generationInput = { prompt, refAssetIds: input.referenceAssetIds, durationS: input.durationS, aspectRatio: input.aspectRatio, quality: input.quality }
    const { jobId } = await ctx.enqueueCapability('video.generate', generationInput, { ...(input.providerId ? { providerId: input.providerId } : {}), maxCostCents: estimate })
    return { data: { jobId, status: 'queued', capability: 'video.generate', generationInput, routing: { requestedProviderId: input.providerId ?? null, maxGenerationCostCents: input.maxGenerationCostCents, estimatedCostCents: estimate }, claimsExcluded: ['Cualquier claim no presente en product'], reviewChecklist: ['Producto y envase coinciden con referencias', 'No aparecen claims nuevos', 'Logo y texto son legibles', 'Derechos de referencias vigentes'] }, evidence: [{ claim: 'Generación encolada con referencias explícitas', sourceRef: { kind: 'job', id: jobId }, confidence: 'high', fetchedAt: new Date().toISOString() }], suggestedActions: [{ kind: 'open_job', label: 'Revisar vídeo', params: { jobId } }] }
  },
})

const blindInput = z.object({ capability: z.enum(['llm.generate', 'image.generate', 'image.upscale', 'audio.tts', 'video.generate', 'video.upscale']), normalizedInput: z.record(z.unknown()).refine(value => Object.keys(value).length > 0, 'Aporta un input normalizado representativo'), samples: z.array(z.object({ providerId: z.string().trim().min(1), assetId: z.string().trim().min(1).optional(), qualityScore: z.number().min(0).max(100), latencyMs: z.number().nonnegative().max(86_400_000), reviewerNotes: z.string().trim().max(1000) })).max(30).default([]).refine(samples => uniqueStrings(samples.map(sample => sample.providerId)), 'Solo se admite una muestra por proveedor'), weights: z.object({ quality: z.number().nonnegative().max(1), cost: z.number().nonnegative().max(1), latency: z.number().nonnegative().max(1) }).refine(weights => weights.quality + weights.cost + weights.latency > 0, 'Al menos un peso debe ser mayor que cero').default({ quality: 0.6, cost: 0.25, latency: 0.15 }), revealProviders: z.boolean().default(false) })
const blindOutput = z.object({ candidates: z.array(z.object({ blindId: z.string(), providerId: z.string().nullable(), tier: z.string(), models: z.array(z.string()), estimateCents: z.number().nullable(), qualityScore: z.number().nullable(), latencyMs: z.number().nullable(), compositeScore: z.number().nullable(), assetId: z.string().nullable(), notes: z.string() })), winnerBlindId: z.string().nullable(), methodology: z.string(), limitations: z.array(z.string()) })

